import { readFileSync } from "node:fs";

const tokens = readFileSync(0, "utf8").trim().split(/\s+/).map(Number);

function spiralOrder(grid: number[][]): number[] {
  const at = (r: number, c: number): number => grid[r]?.[c] ?? 0;
  const result: number[] = [];
  let top = 0;
  let bottom = grid.length - 1;
  let left = 0;
  let right = (grid[0]?.length ?? 0) - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) {
      result.push(at(top, c));
    }
    top++;
    for (let r = top; r <= bottom; r++) {
      result.push(at(r, right));
    }
    right--;
    if (top <= bottom) {
      for (let c = right; c >= left; c--) {
        result.push(at(bottom, c));
      }
      bottom--;
    }
    if (left <= right) {
      for (let r = bottom; r >= top; r--) {
        result.push(at(r, left));
      }
      left++;
    }
  }
  return result;
}

